// Échelles des niveaux de compétence - Enseignement primaire (MEQ, 2002), échelons 1 à 10.
// Fichier généré à partir du document officiel; descriptions reprises telles quelles.
window.ECHELLES_PRIMAIRE = {
  'math_resoudre': { titre: 'Résoudre une situation-problème mathématique', echelons: [
    { n: 1, cycle: 1, texte: 'L\'élève résout des situations-problèmes portant sur un thème de la mathématique (arithmétique, mesure, géométrie, probabilité, statistique), comportant des données complètes et nécessitant en général une seule étape de solution. L’élève fait appel régulièrement à une personne-ressource pour déterminer la tâche et dégager les données utiles à l’aide, par exemple, d’objets, de mots ou d’images. Il démontre une compréhension limitée des situations-problèmes et a tendance à employer une seule stratégie (p. ex.: la manipulation d’objets). Il communique, dans ses propres mots, certaines étapes de ses solutions.' },
    { n: 2, cycle: 1, texte: 'L\'élève résout des situations-problèmes dans plus d\'un thème de la mathématique, comportant des données complètes et nécessitant dans certains cas plus d\'une étape de solution. L\'élève fait appel à une personne-ressource au besoin pour déterminer la tâche et dégager les données utiles à l’aide, par exemple, d’objets, de mots, d’images ou de dessins. Il démontre une compréhension partielle des situations-problèmes et applique quelques stratégies (p. ex.: essais et erreurs). Il communique dans ses propres mots et, en insérant des termes mathématiques, certaines étapes de ses solutions.' },
    { n: 3, cycle: 1, texte: 'L\'élève résout des situations-problèmes variées dans plus d\'un thème de la mathématique, comportant à l\'occasion des données superflues et nécessitant souvent plus d\'une étape de solution. L\'élève fait appel à une personne-ressource au besoin dans certaines situations-problèmes plus complexes pour déterminer la tâche et dégager les données utiles à l’aide, par exemple, d’objets, de dessins, de tableaux, de diagrammes, de symboles ou de mots. Il démontre une compréhension générale des situations-problèmes et applique des stratégies plus variées (par exemple, utilisation de situations-problèmes similaires déjà résolues). Il communique, dans ses propres mots et à l\'occasion à l’aide du langage mathématique, les principales étapes de ses solutions.' },
    { n: 4, cycle: 1, texte: 'L\'élève résout des situations-problèmes variées comportant des données complètes ou superflues. Il détermine la tâche et dégage les données utiles en ayant recours à différents modes de représentation tels des objets, des dessins, des tableaux, des diagrammes, des symboles ou des mots. Il élabore une solution qui comporte une ou deux étapes et vérifie occasionnellement le résultat obtenu. Il communique verbalement ou par écrit ses solutions en utilisant un langage mathématique élémentaire.' },
    { n: 5, cycle: 2, texte: 'L\'élève résout des situations-problèmes variées comportant des données complètes ou superflues. Il détermine la tâche et dégage les données utiles en ayant recours à différents modes de représentation. À la suite d’un questionnement d’une personne-ressource, il anticipe le résultat. Il élabore une solution qui comporte, à l’occasion, quelques étapes de solution. L’élève fait appel régulièrement à une personne-ressource tout au long de sa démarche de validation de sa solution (démarche et résultat). Il communique verbalement ou par écrit certaines étapes de ses solutions en utilisant un langage mathématique approprié.' },
    { n: 6, cycle: 2, texte: 'L\'élève résout des situations-problèmes variées comportant à l\'occasion des données implicites. L\'élève fait appel à une personne-ressource au besoin dans certaines situations-problèmes plus complexes pour déterminer la tâche ou les données utiles en ayant recours à différents modes de représentation. Il anticipe le résultat et élabore une solution qui comporte souvent quelques étapes de solution. À la suite d’un questionnement d’une personne-ressource, il complète la validation de sa solution (démarche et résultat). Il communique verbalement ou par écrit les principales étapes de ses solutions en utilisant un langage mathématique approprié.' },
    { n: 7, cycle: 2, texte: 'L\'élève résout des situation-problèmes variées comportant des données complètes, superflues ou implicites. Il anticipe le résultat et élabore une solution qui comporte quelques étapes. Il fait appel à une personne-ressource au besoin pour valider certaines étapes de sa solution. Il communique verbalement ou par écrit ses solutions en utilisant un langage mathématique approprié.' },
    { n: 8, cycle: 3, texte: 'L\'élève résout des situations-problèmes variées comportant des données complètes, superflues ou implicites. L\'élève détermine la tâche et dégage les données utiles en ayant recours à différents modes de représentation. Il anticipe le résultat et élabore une solution qui comporte à l’occasion plusieurs étapes de solution. À la suite d’un rappel d’une personne-ressource, l’élève valide sa solution (démarche et résultat). Il communique de façon structurée, verbalement ou par écrit, les principales étapes de ses solutions. À l’écrit, il se soucie du respect des règles et des conventions dans l’utilisation des termes, de la notation, des symboles et des modes de représentation.' },
    { n: 9, cycle: 3, texte: 'L\'élève résout des situations-problèmes variées comportant à l\'occasion des données manquantes. L\'élève fait appel à une personne-ressource, au besoin dans certaines situations-problèmes plus complexes, pour déterminer la tâche ou les données utiles en ayant recours à différents modes de représentation. Il anticipe le résultat et élabore une solution qui comporte souvent plusieurs étapes de solution. Il valide occasionnellement sa solution (démarche et résultat). Il communique de façon structurée, verbalement ou par écrit, ses solutions. À l’écrit, il respecte les règles et les conventions dans l’utilisation des termes, de la notation, des symboles et des modes de représentation.' },
    { n: 10, cycle: 3, texte: 'L\'élève résout des situations-problèmes variées comportant des données complètes, superflues, implicites ou manquantes. Il détermine la tâche et dégage les données utiles en ayant recours à différents modes de représentation. Il anticipe le résultat et élabore une solution qui comporte plusieurs étapes. Il valide régulièrement sa solution (démarche et résultat). Il la communique verbalement ou par écrit en utilisant un langage mathématique rigoureux.' },
  ] },
  'math_raisonner': { titre: 'Raisonner à l’aide de concepts et de processus mathématiques', echelons: [
    { n: 1, cycle: 1, texte: 'L\'élève représente des nombres naturels à l\'aide d\'objets. Il éprouve des difficultés à travailler avec des nombres naturels inférieurs à 100. L\'élève additionne et soustrait à l\'aide de matériel concret. L\'élève compare, ordonne et classifie des objets selon une dimension. Il est capable de se repérer dans l\'espace, de nommer et de comparer des figures planes et des solides à des objets de son environnement. L\'élève vérifie par l\'expérimentation la possibilité d\'obtenir un résultat dans une expérience liée au hasard. Avec de l\'aide, il dégage des données de tableaux et de diagrammes à bandes ou à pictogrammes.' },
    { n: 2, cycle: 1, texte: 'L\'élève lit, écrit et ordonne des nombres naturels inférieurs à 100. Il peut éprouver des difficultés en fonction de la taille des nombres. L\'élève reconnaît les opérations d\'addition et de soustraction selon certains sens. Il peut additionner et soustraire des nombres naturels, mentalement ou par écrit, à l\'aide de processus personnels. L\'élève estime et mesure les dimensions d\'objets à l\'aide d\'unités de mesure non conventionnelles. Il compare et construit certains solides. L\'élève prédit un résultat à l\'aide de termes comme certain, possible ou impossible. Il interprète des données de diagrammes à bandes ou à pictogrammes. Avec de l\'aide, il recueille des données, les organise dans un tableau et en fait une interprétation simple.' },
    { n: 3, cycle: 1, texte: 'L\'élève démontre une compréhension du sens des nombres pour les nombres naturels inférieurs à 1 000. L\'élève fait des liens entre l\'addition et la soustraction, en reconnaît les différents sens (p. ex.: ajout, réunion, retrait) et est habile à en estimer le résultat. Il peut additionner et soustraire des nombres naturels, mentalement ou par écrit, à l\'aide de processus personnels. L\'élève estime et mesure le temps à l\'aide d\'unités conventionnelles et des longueurs à l\'aide d\'unités non conventionnelles et conventionnelles. Il choisit l\'unité de mesure la plus appropriée pour mesurer une longueur. Il compare et construit des figures planes et des solides. L\'élève prédit un résultat et dénombre des résultats possibles d\'une expérience aléatoire simple (p. ex.: dé, monnaie). Il recueille des données (questionnaire, instrument de mesure, documentation) et les organise dans un tableau. Il les représente à l\'aide d\'un diagramme à bandes ou à pictogrammes et en fait une interprétation simple.' },
    { n: 4, cycle: 2, texte: 'L\'élève démontre une compréhension partielle des nombres décimaux. Il a besoin d\'aide pour lire, écrire et représenter des nombres décimaux. L\'élève additionne et soustrait des nombres naturels à l\'aide de processus conventionnels. L\'élève estime et mesure le temps. Il établit des relations entre les unités de mesure de longueur. Il décrit des prismes et des pyramides. L\'élève simule des expériences aléatoires simples. Il recueille des données et en dégage des observations. Par exemple, il observe que le chiffre 6 est apparu 3 fois au cours de 20 lancers d\'un dé. Il interprète les résultats d\'une enquête à partir d\'un diagramme à ligne brisée.' },
    { n: 5, cycle: 2, texte: 'L\'élève lit, écrit et ordonne des nombres naturels inférieurs à 100 000. Il démontre une compréhension partielle des fractions et fait des liens entre celles-ci et les nombres décimaux. L\'élève reconnaît certains sens de la multiplication et de la division. Il peut multiplier et diviser des nombres naturels, mentalement ou par écrit, à l\'aide de processus personnels. L\'élève estime, mesure ou calcule des surfaces à l\'aide d\'unités non conventionnelles et effectue du repérage dans le plan. Il construit des frises et des dallages à l\'aide de réflexions. L\'élève démontre une compréhension du hasard par l\'emploi de mots comme également probable et moins probable. Il représente les données issues d\'une enquête à l\'aide d\'un diagramme à ligne brisée.' },
    { n: 6, cycle: 2, texte: 'L\'élève démontre une compréhension du sens des nombres pour les nombres naturels inférieurs à 100 000 et les nombres décimaux jusqu\'à l\'ordre des centièmes. Il représente et reconnaît des fractions à l\'aide de schémas. L\'élève fait des liens entre les quatre opérations, en reconnaît les différents sens (p. ex.: ajout, réunion, retrait, arrangement rectangulaire, partage, etc.) et est habile à en estimer le résultat. Il effectue, mentalement ou par écrit, les opérations sur les nombres naturels à l\'aide de processus personnels et conventionnels dans le cas de l\'addition et de la soustraction. Il additionne et soustrait, mentalement ou par écrit, des nombres décimaux jusqu\'à l\'ordre des centièmes. L\'élève estime, mesure ou calcule des longueurs (dont le périmètre) à l\'aide d\'unités de mesure conventionnelles. Il choisit l\'unité de mesure la plus appropriée pour mesurer une longueur. Il estime, mesure ou calcule des surfaces et des volumes à l\'aide d\'unités de mesure non conventionnelles. Il peut aussi estimer, mesurer ou calculer le temps. Il classifie des quadrilatères. Il construit des frises et des dallages à l\'aide de réflexions. L\'élève dénombre tous les résultats possibles d\'une expérience aléatoire à partir de simulations. Il recueille des données (questionnaire, instrument de mesure, documentation) et les organise dans un tableau. Il les représente à l\'aide de diagrammes et en fait une interprétation.' },
    { n: 7, cycle: 3, texte: 'L\'élève compare des fractions et reconnaît des fractions équivalentes. L\'élève fait des liens entre les opérations, en reconnaît les différents sens (p. ex.: ajout, réunion, retrait, arrangement rectangulaire, partage, etc.) et est habile à en estimer le résultat. Il effectue, mentalement ou par écrit, des opérations sur des nombres naturels à l\'aide de processus conventionnels. L\'élève estime, mesure ou calcule des longueurs et des surfaces. Dans chaque cas, il établit des relations entre les unités de mesure. Il effectue du repérage dans le plan cartésien. Il construit des frises et des dallages à l\'aide de translations. L\'élève dénombre les résultats possibles d\'une expérience aléatoire à l\'aide de tableaux, de diagrammes en arbre. Il interprète les résultats d\'une enquête à partir d\'un diagramme circulaire.' },
    { n: 8, cycle: 3, texte: 'L\'élève lit, écrit et ordonne des nombres naturels inférieurs à 1 000 000. Il sait manipuler des nombres sous la forme fractionnaire et décimale. L\'élève fait des liens entre les opérations, en reconnaît les différents sens (p. ex.: ajout, réunion, retrait, arrangement rectangulaire, partage, etc.) et est habile à en estimer le résultat. Il effectue, mentalement ou par écrit, des opérations sur des nombres décimaux à l\'aide de processus conventionnels. L\'élève estime, mesure ou calcule des volumes et des capacités. Dans chaque cas, il établit des relations entre les unités de mesure. Il estime et mesure des angles. Il classifie des triangles. L\'élève démontre une compréhension de la moyenne arithmétique à l\'aide de matériel concret et de schémas. L\'élève réalise une enquête et en tire des conclusions.' },
    { n: 9, cycle: 3, texte: 'L\'élève démontre une compréhension du sens des nombres pour les nombres naturels inférieurs à 1 000 000 et les nombres décimaux jusqu\'à l\'ordre des millièmes. Il comprend les liens entre nombres naturels et nombres entiers. L\'élève fait des liens entre les quatre opérations, en reconnaît les différents sens (p. ex.: ajout, réunion, retrait, arrangement rectangulaire, partage, etc.) et est habile à en estimer le résultat. Il effectue, mentalement ou par écrit, des opérations sur des nombres naturels et décimaux. Dans le cas des nombres naturels, il peut effectuer des suites d\'opérations en respectant leur priorité. Il additionne, soustrait et multiplie des fractions à l\'aide de schémas ou de matériel concret. L\'élève estime, mesure ou calcule des longueurs, des surfaces, des volumes, des angles, des capacités, des masses, la température et le temps. Mis à part la température et les angles, il établit des relations entre les unités de mesure conventionnelles dans chaque cas. Il classifie des triangles. Il construit des frises et des dallages à l\'aide de translations. Il effectue du repérage dans le plan cartésien. L\'élève compare les résultats possibles d\'une expérience aléatoire aux résultats théoriques connus. Il calcule la moyenne arithmétique. L\'élève réalise une enquête, en tire des conclusions et suggère des prolongements.' },
  ] },
  'fra_lecture': { titre: 'Lire des textes variés', echelons: [
    { n: 1, cycle: 1, texte: 'L’élève fait semblant de lire lorsqu’il feuillette un livre. Il parvient à se le raconter intérieurement ou à le raconter à autrui en s’appuyant notamment sur les illustrations. Dans les textes qu’il aborde, il reconnaît quelques mots familiers ou déjà vus en classe. Il réussit à suivre des consignes simples comprenant surtout des mots connus. Il cherche aussi à donner du sens aux écrits qu’il rencontre autour de lui et il en parle volontiers.' },
    { n: 2, cycle: 1, texte: 'L’élève lit des petits messages ou des textes courts, simples et illustrés constitués majoritairement de mots familiers et d’usage fréquent. Afin de construire du sens, il utilise, avec de l’aide, des stratégies de reconnaissance et d’identification de mots telles que les correspondances entre les lettres et les sons ainsi que le recours au contexte et aux illustrations. Il parvient à accomplir des tâches très simples liées à diverses intentions de lecture. Il réagit au texte dans la mesure où il est sollicité.' },
    { n: 3, cycle: 1, texte: 'L’élève lit des textes courants et littéraires, simples et illustrés, dont la structure est généralement prévisible. Pour comprendre l’essentiel d’un texte, il utilise les stratégies appropriées et rappelées par l’enseignant. Lorsqu’il accomplit des tâches simples liées à diverses intentions de lecture, il dégage les informations explicites nécessaires. Quand il réagit au texte, il exprime ses réactions en ayant recours surtout au dessin ou à la parole.' },
    { n: 4, cycle: 1, texte: 'L’élève lit des textes courants et littéraires généralement courts, illustrés et présentant un niveau de difficulté approprié. Afin de comprendre les textes qu’il lit, l’élève a recours aux principales stratégies apprises. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture, il dégage la plupart des informations explicites contenues dans un ou plusieurs courts textes. De façon générale, il réagit spontanément aux textes et ses réactions, souvent liées à ses expériences personnelles, peuvent se manifester par le recours à la parole, au dessin, au mime, au non verbal et quelquefois à l’écrit.' },
    { n: 5, cycle: 2, texte: 'L’élève lit des textes courants et littéraires, proposant un défi approprié, généralement illustrés et présentés sur différents supports médiatiques. Il utilise la plupart des stratégies auxquelles il a été initié pour comprendre les textes. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture, il dégage les éléments d’information explicites et, à l’occasion, certains éléments d’information implicites liés à ses connaissances et à ses expériences personnelles. Il réagit aux textes qu’il lit et ses réactions, orales et parfois écrites, s’appuient aussi sur ses expériences personnelles.' },
    { n: 6, cycle: 2, texte: 'L’élève lit des textes courants et littéraires, proposant un défi approprié, souvent illustrés et présentés sur différents supports médiatiques. Il utilise les différentes stratégies apprises pour mieux saisir l’information. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture ou rattachées aux disciplines scolaires, il parvient à dégager des éléments d’information explicites et, parfois, quelques-uns qui sont implicites. Il réagit aux textes qu’il lit surtout en les reliant à ses expériences personnelles et parfois à d’autres textes qu’il a lus.' },
    { n: 7, cycle: 2, texte: 'L’élève lit des textes courants et littéraires qui peuvent être illustrés et présentés sur différents supports médiatiques. Dans des textes qui présentent pour lui un défi raisonnable, il fait appel à diverses stratégies, dont certaines lui permettent de mieux saisir et organiser l’information. Pour répondre à diverses intentions de lecture et pour accomplir des tâches significatives dans plusieurs disciplines scolaires, il réussit à dégager les éléments d’information explicites et parfois ceux qui sont implicites. Lorsqu’il réagit à certains aspects des textes qu’il lit, il le fait généralement de façon pertinente en les reliant à ses expériences personnelles et à d’autres textes qu’il a lus.' },
    { n: 8, cycle: 3, texte: 'L’élève lit une variété de textes courants et littéraires, présentés sur différents supports médiatiques et proposant un défi raisonnable. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture dans différentes disciplines scolaires, il dégage avec efficacité les éléments d’information explicites et quelques éléments d’information implicites contenus dans un même texte et, à l’occasion, dans plusieurs textes, en utilisant les stratégies pertinentes. Il réagit à divers aspects des textes en les reliant à ses expériences personnelles ou scolaires et parfois à d’autres lectures.' },
    { n: 9, cycle: 3, texte: 'L’élève lit une variété de textes courants et littéraires, présentés sur différents supports médiatiques et proposant un défi raisonnable. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture dans différents contextes et disciplines scolaires, il dégage les éléments d’information explicites et implicites contenus dans plusieurs textes en utilisant efficacement des stratégies pertinentes. Il réagit à plusieurs aspects des textes et ses réactions témoignent de son interprétation personnelle, de ses connaissances, de ses expériences personnelles ou scolaires ainsi que de ses autres lectures.' },
    { n: 10, cycle: 3, texte: 'L’élève lit une grande diversité de textes courants et littéraires, de niveaux de difficulté variables, et présentés sur différents supports médiatiques. Lorsqu’il accomplit des tâches liées à diverses intentions de lecture dans différents contextes et disciplines scolaires, il dégage les éléments d’information tant explicites qu’implicites contenus dans un ou plusieurs textes en ayant recours à des stratégies variées et pertinentes. Il réagit aux différents aspects des textes et ses réactions témoignent de ses champs d’intérêt, de son interprétation personnelle, de ses connaissances, de ses expériences personnelles ou scolaires ainsi que de ses autres lectures.' },
  ] },
  'fra_ecriture': { titre: 'Écrire des textes variés', echelons: [
    { n: 1, cycle: 1, texte: 'L’élève apprivoise l’écriture en faisant des tentatives graphiques, en inventant des symboles ou en utilisant des lettres correspondant parfois aux sons. Il reproduit ou transforme légèrement de petits messages ou de très courts textes rédigés collectivement ou présents dans son environnement immédiat. Dans différentes situations, il transcrit, selon la technique apprise, les lettres minuscules et majuscules tout en laissant des espaces variables entre les lettres et entre les mots de son texte.' },
    { n: 2, cycle: 1, texte: 'L’élève écrit pour lui-même ou pour communiquer avec autrui des messages ou de très courts textes en utilisant principalement les mots travaillés en classe. Influencées par la langue orale, ses phrases sont simples, parfois incomplètes et comportent des répétitions en raison de son vocabulaire limité. Il sait orthographier les mots les plus fréquents travaillés en classe, même s’il invente l’orthographe des mots non appris. La plupart du temps, il trace lisiblement les lettres minuscules et majuscules et il laisse les espaces requis entre les lettres et les mots.' },
    { n: 3, cycle: 1, texte: 'L’élève produit de courts textes pour s’exprimer et pour communiquer avec autrui. Ses phrases, encore calquées sur l’oral, sont courtes, juxtaposées et peu variées. Avec de l’aide, il utilise la majuscule et le point. Son vocabulaire s’élargit et il lui arrive d’utiliser des mots nouveaux issus de ses lectures. De plus, il sait orthographier un bon nombre de mots usuels travaillés en classe, même s’il s’appuie sur les correspondances entre les lettres et les sons pour les mots non appris. Il applique, avec le soutien de l’enseignant, quelques stratégies de mise en texte, de révision et de correction. Son écriture, script ou cursive, est généralement lisible.' },
    { n: 4, cycle: 1, texte: 'L’élève rédige une variété de courts textes pour répondre à des besoins de base qui se manifestent dans sa vie personnelle et scolaire. Ainsi, il produit des textes suivis dont la structure est simple et qui contiennent des idées liées au sujet traité. Ses phrases courtes sont généralement bien construites et habituellement délimitées par une majuscule et un point. Son vocabulaire est simple et courant, mais il a encore recours à la répétition. De plus, il sait orthographier la majorité des mots usuels appris en classe. Dans les cas les plus simples, il accorde les déterminants avec les noms en mettant les marques du féminin et du pluriel. Tout au long de sa démarche d’écriture, il utilise, avec le soutien de l’enseignant, les stratégies apprises. Selon la situation, il calligraphie en script ou en cursive afin qu’on puisse le lire facilement.' },
    { n: 5, cycle: 2, texte: 'L’élève rédige des textes simples, de longueurs variables pour répondre à diverses intentions, et ce, dans des contextes de plus en plus variés. Avec de l’aide, il choisit les idées appropriées et les organise de manière logique ou chronologique. Ses phrases, généralement bien construites, sont délimitées par la majuscule et le point. À l’occasion, il a recours à quelques connecteurs simples pour relier les phrases entre elles. Son vocabulaire simple et courant se diversifie. De plus, il sait orthographier les mots appris en classe et il effectue les accords du déterminant et de l’adjectif avec le nom, dans la plupart des cas simples. Avec de l’aide, il a recours à quelques stratégies et commence à utiliser des outils de référence. Il calligraphie lisiblement et utilise l’écriture script ou cursive selon le projet.' },
    { n: 6, cycle: 2, texte: 'L’élève rédige des textes variés, parfois un peu élaborés, pour répondre à diverses intentions, et ce, dans différents contextes et disciplines scolaires. Ses idées sont souvent regroupées et ordonnées de manière logique ou chronologique. Ses phrases sont parfois longues et assez bien construites, malgré certaines maladresses dans l’utilisation des connecteurs. En plus de recourir à la majuscule et au point, il utilise la virgule dans les cas d’énumération simple. Son vocabulaire est assez varié et généralement correct. Il sait orthographier un bon nombre de mots d’usage fréquent et effectue les accords dans le groupe du nom ainsi que l’accord du verbe avec son sujet, dans les cas les plus simples. Il utilise quelques stratégies et consulte des outils de référence mis à sa disposition. Il calligraphie lisiblement et utilise facilement l’écriture script ou cursive, selon le projet.' },
    { n: 7, cycle: 2, texte: 'L’élève rédige des textes variés, souvent assez élaborés, dans différents contextes et disciplines scolaires. Ses textes comportent généralement plusieurs idées ordonnées de manière logique ou chronologique à l’intérieur d’un paragraphe ou de quelques courts paragraphes qui ne sont pas nécessairement reliés entre eux. Ses phrases, souvent longues mais peu variées, sont parfois reliées à l’aide de connecteurs courants et elles tiennent généralement compte des éléments de syntaxe et de ponctuation vus en classe. L’élève utilise un vocabulaire varié, correct et parfois précis. Il sait orthographier la plupart des mots d’usage fréquent et il effectue l’accord du déterminant et de l’adjectif avec le nom et l’accord du verbe avec le sujet dans les cas simples. Il recourt à plusieurs stratégies et consulte divers outils de référence mis à sa disposition. Selon la situation de communication, il calligraphie lisiblement en écriture script ou cursive et il utilise occasionnellement un logiciel de traitement de texte.' },
    { n: 8, cycle: 3, texte: 'L’élève rédige des textes variés dans différents contextes et disciplines scolaires, et ce, en tenant compte à l’occasion des destinataires. Il choisit ses idées et les organise selon le genre de textes en les regroupant, s’il y a lieu, à l’intérieur de paragraphes. Ses phrases, assez variées et souvent reliées entre elles par des connecteurs courants, tiennent compte de plusieurs éléments de syntaxe et de ponctuation vus en classe. Le vocabulaire utilisé est varié, assez précis et parfois évocateur. Il sait orthographier les mots d’usage fréquent et il respecte généralement les règles d’accord dans le groupe du nom et celles de l’accord du verbe et de l’attribut avec le sujet. Il choisit la plupart du temps des stratégies pertinentes et il consulte divers outils de référence. Il calligraphie lisiblement et son écriture, script ou cursive, est adaptée au projet ou à la tâche. Il utilise, s’il y a lieu, un support technologique.' },
    { n: 9, cycle: 3, texte: 'L’élève rédige une grande variété de textes, de longueurs variables, dans différents contextes ou disciplines en tenant compte, la plupart du temps, des destinataires. Ses idées, exprimées clairement, sont regroupées adéquatement et séparées en paragraphes, s’il y a lieu. Ses phrases sont variées, généralement bien structurées, bien ponctuées et reliées entre elles par des connecteurs courants. Le vocabulaire qu’il utilise est varié, précis ou évocateur, compte tenu de la situation d’écriture. Il sait orthographier la majorité des mots appris et il respecte les règles d’accord dans le groupe du nom et plus généralement celles de l’accord du verbe et de l’attribut. Il fait appel à des stratégies pertinentes et consulte spontanément les outils de référence. Il calligraphie lisiblement et avec aisance tout en choisissant le format ou le support technologique en fonction du projet ou de la tâche.' },
    { n: 10, cycle: 3, texte: 'L’élève rédige avec une certaine efficacité des textes variés et adaptés en fonction de leurs destinataires dans différents contextes et disciplines scolaires. Dans des textes comportant généralement plusieurs paragraphes, il s’exprime de façon claire et, au besoin, détaillée. Il développe ses idées selon un ordre logique ou chronologique et il établit des liens entre les phrases et entre les paragraphes au moyen de connecteurs courants et, la plupart du temps, appropriés. Ses phrases, relativement variées et souvent élaborées, sont généralement bien construites et bien ponctuées. Pour personnaliser son message et préciser sa pensée, il utilise un vocabulaire varié, précis et évocateur. Il sait orthographier les mots appris et il effectue adéquatement les accords dans le groupe du nom de même que l’accord du verbe, de l’attribut et du participe passé avec l’auxiliaire être. Il fait également appel à des stratégies appropriées et utilise avec profit les outils de référence et les technologies à sa disposition pour améliorer ses écrits et leur présentation.' },
  ] },
  'fra_oral': { titre: 'Communiquer oralement', echelons: [
    { n: 1, cycle: 1, texte: 'L’élève s’exprime spontanément ou sur demande au cours des échanges verbaux en classe, mais sans toujours tenir compte du sujet abordé. Pour compléter ses énoncés, il utilise souvent des gestes ou d’autres comportements non verbaux. Centré surtout sur lui-même, il se préoccupe peu du fait d’être compris. Il intervient plus facilement lorsque les échanges d’idées se déroulent en petits groupes.' },
    { n: 2, cycle: 1, texte: 'L’élève intervient en classe au cours des interactions en petits groupes. Lorsqu’il explore verbalement un sujet avec ses pairs, il s’éloigne quelquefois du thème de la discussion. Au cours des moments de partage de ses propos, il est surtout centré sur ce qu’il dit, même s’il s’intéresse parfois aux réactions des autres. Durant de courts laps de temps, il parvient à diriger son attention sur les propos d’autrui.' },
    { n: 3, cycle: 1, texte: 'L’élève interagit avec ses pairs au cours des discussions et autres formes d’échanges d’idées en respectant quelques règles de communication. Au moment de l’exploration d’un sujet avec ses pairs, il intervient spontanément en se centrant sur le sujet traité. Lorsqu’il partage ses propos, il produit, la plupart du temps, des énoncés clairs et compréhensibles. De plus, il commence à s’intéresser aux propos d’autrui et à se montrer sensible aux réactions de ses interlocuteurs.' },
    { n: 4, cycle: 1, texte: 'L’élève prend la parole au cours des interactions en classe et il respecte les règles de communication établies. Dans différents contextes, il explore avec ses pairs des sujets familiers. Lorsqu’il partage ses propos, il formule clairement ses idées et utilise un vocabulaire simple et correct. La plupart du temps, ses réactions témoignent d’une écoute appropriée. Dans les situations qui le justifient, il articule nettement et il ajuste, au besoin, le volume de sa voix. Déjà un peu conscient de l’existence de différents registres de langue, il essaie, à l’occasion, d’adapter sa façon de parler en fonction des personnes et de la situation.' },
    { n: 5, cycle: 2, texte: 'L’élève participe, à l’occasion d’échanges d’idées ou de discussions en petits groupes ou en grand groupe, à l’exploration de divers sujets, souvent moins familiers, tout en respectant quelques règles de communication établies. Il cherche alors à préciser sa pensée en prenant à l’occasion des risques sur le plan de la formulation ou par l’utilisation de nouveaux mots ou de nouvelles expressions. Lorsqu’il partage ses propos, il exprime assez clairement ses idées et utilise un vocabulaire souvent varié. Il a davantage conscience de ses interlocuteurs et il lui arrive parfois d’ajuster son registre de langue, le volume de sa voix et son débit. Au cours des différentes activités de communication, il manifeste une meilleure écoute des propos d’autrui et il y réagit généralement de façon pertinente.' },
    { n: 6, cycle: 2, texte: 'L’élève participe activement aux différents échanges d’idées et aux discussions proposées afin d’explorer avec ses pairs différents sujets, souvent reliés à la vie de la classe ou aux autres disciplines. Il tient généralement compte des règles de communication établies. Dans divers contextes, lorsqu’il partage ses propos, il s’exprime avec clarté et cohérence et il utilise un vocabulaire varié. Pour tenir compte de la situation de communication et de ses interlocuteurs, il ajuste souvent ses propos, son registre de langue, le volume de sa voix et son débit. Au cours des activités d’échange ou de partage de propos, il manifeste son ouverture à ceux d’autrui en ayant recours à quelques stratégies d’écoute telles que l’utilisation du langage non verbal ou encore la répétition ou la reformulation de ce qui a été dit.' },
    { n: 7, cycle: 2, texte: 'L’élève participe régulièrement à diverses formes d’échange verbal portant sur une grande variété de sujets à sa portée. Lorsqu’il explore verbalement un sujet, il explicite ses propos et il formule parfois des questions pour vérifier ou pour approfondir sa compréhension. Tout en respectant les règles établies, il intervient au moment opportun au cours des discussions. Lorsqu’il partage ses propos, il s’exprime habituellement de façon cohérente et structurée et ses formulations se révèlent adéquates. Dans ce contexte, il apporte parfois des précisions ou des explications en utilisant un vocabulaire juste et précis. La plupart du temps, il tient compte de la situation et des interlocuteurs en utilisant le volume, le débit et l’intonation appropriés, tout en ayant recours au registre de langue adapté. Au cours des activités d’échange ou de partage de propos, ses réactions témoignent d’une écoute active.' },
    { n: 8, cycle: 3, texte: 'L’élève, à l’occasion d’échanges d’idées et de discussions, explore avec une certaine aisance divers sujets reliés à sa vie scolaire. Lorsqu’il prend la parole pour partager ses propos, il s’exprime avec une syntaxe correcte et un vocabulaire assez précis. Il tient généralement compte de ses interlocuteurs et réussit souvent à percevoir des signes non verbaux d’intérêt, d’ennui ou d’incompréhension même s’il ne parvient pas toujours à modifier ses propos de manière appropriée. Au cours des activités d’échange et de partage, il a recours au langage non verbal pour manifester son intérêt, son incompréhension, son accord ou son désaccord. Généralement, il suit les règles convenues pour assurer le bon fonctionnement des échanges d’idées et a recours à quelques stratégies utiles de communication orale.' },
    { n: 9, cycle: 3, texte: 'L’élève participe activement aux différents échanges d’idées et aux discussions permettant d’explorer avec ses pairs différentes facettes des sujets reliés à la vie de la classe et aux disciplines scolaires. Dans ces différents contextes, lorsqu’il partage ses propos, il exprime ses idées avec efficacité en utilisant souvent un vocabulaire spécifique. Lorsqu’il se rend compte qu’il n’est pas compris, il reformule, explique ou précise ses énoncés. De plus en plus conscient des besoins de ses interlocuteurs, il s’efforce d’ajuster en conséquence ses propos et s’il y a lieu, son registre de langue ainsi que le volume de sa voix, son débit et son rythme. Il adopte une attitude d’ouverture aux propos d’autrui en les soutenant ou en les valorisant. Si nécessaire, il vérifie sa compréhension en posant des questions. Au cours des différentes activités de communication orale, il utilise de plus en plus de stratégies efficaces, tout en respectant les règles établies.' },
    { n: 10, cycle: 3, texte: 'L’élève explore avec aisance de nombreux sujets avec d’autres personnes afin de préciser sa pensée. Lorsqu’il partage ses propos, il les exprime avec clarté, rigueur et efficacité dans divers contextes d’interaction reliés à la vie de la classe ou de l’école. À l’occasion de ces échanges d’idées, il démontre sa compréhension en reformulant souvent avec justesse ce qui a été exprimé ou en posant des questions pertinentes et appropriées pour obtenir des clarifications, des précisions ou de la rétroaction. Il parvient aussi à confronter ses idées à celles d’autrui et à nuancer son point de vue à l’aide d’un vocabulaire pertinent, varié et suffisamment précis. Capable de tenir compte de la diversité de ses interlocuteurs, il adapte généralement ses propos à leurs réactions et à la situation de communication en utilisant notamment un registre de langue approprié. Le volume de sa voix, le débit et le rythme sont adaptés à la situation. Au cours des échanges d’idées et des discussions, il respecte également les règles de communication établies et utilise des stratégies appropriées.' },
  ] },
  'sciences_global': { titre: 'Proposer des explications ou des solutions à des problèmes d’ordre scientifique et technologique', echelons: [
    { n: 1, cycle: 2, texte: 'L’élève repère quelques caractéristiques d’une problématique. Avec de l’aide, il fait appel à ses connaissances antérieures pour anticiper des idées d’explication ou de solution liées à la problématique. Après un rappel, il recourt à l’observation, à la manipulation, à des sources d’information proposées (pairs, experts, ressources documentaires) pour trouver des idées et repérer des pistes d’explication ou de solution. Avec de l’aide, il conçoit une explication, une solution, une façon de faire et la met en œuvre. Il utilise les outils et les instruments suggérés lorsqu’il met en œuvre ses explications ou ses solutions. Avec de l’aide, il communique ses explications ou ses solutions en utilisant quelques termes ou expressions spécialisés dans leur acception scientifique et technologique et au moins un mode de représentation.' },
    { n: 2, cycle: 2, texte: 'L’élève repère quelques caractéristiques d’ordre scientifique ou technologique d’une problématique et dit dans ses propres mots en quoi elle consiste. En faisant appel à ses connaissances antérieures et avec de l’aide au besoin, il anticipe des idées d’explication ou de solution liées à la problématique. Il recourt à l’observation, à la manipulation, à des sources d’information (pairs, experts, ressources documentaires) pour dégager des pistes d’explication ou de solution. Il fait appel à une personne-ressource au besoin soit pour choisir une explication, une solution, une façon de faire, soit pour mettre en œuvre l’explication ou la solution choisie. Avec de l’aide, il utilise de façon appropriée des outils et des instruments lorsqu’il met en œuvre ses explications ou ses solutions. Il communique ses explications ou ses solutions en utilisant quelques termes ou expressions spécialisés dans leur acception scientifique et technologique et quelques modes de représentation.' },
    { n: 3, cycle: 2, texte: 'L’élève reconnaît quelques caractéristiques d’ordre scientifique ou technologique d’une problématique. Il fait des liens entre les caractéristiques et la problématique. À l’occasion, il reformule la problématique dans ses propres mots. En faisant appel à ses connaissances antérieures, il anticipe des idées d’explication ou de solution liées à la problématique. Il recourt à l’observation, à la manipulation, à des sources d’information variées pour choisir une ou des pistes d’explication ou de solution. Il choisit une façon de faire au regard de l’explication ou de la solution retenue et la met en œuvre avec de l’aide au besoin. Avec de l’aide, il choisit les outils et les instruments requis et les utilise de façon appropriée. Il communique ses explications ou ses solutions en utilisant des termes ou expressions spécialisés dans leur acception scientifique et technologique et différents modes de représentation.' },
    { n: 4, cycle: 3, texte: 'L’élève reconnaît des caractéristiques d’ordre scientifique ou technologique d’une problématique. Avec de l’aide, il fait des liens entre ses connaissances antérieures et ses explications provisoires pour anticiper des idées d’explication ou de solution. Il recourt à l’observation, à la manipulation, à des sources d’information variées (pairs, experts, ressources documentaires) pour choisir une ou des pistes d’explication ou de solution et explicite ses choix. Il choisit avec de l’aide un moyen approprié pour recueillir des informations au cours de la mise en œuvre de sa solution ou de son explication. Avec de l’aide, il choisit les outils et les instruments requis et les utilise de façon appropriée. Avec de l’aide, il évalue les résultats obtenus et propose si nécessaire des modifications à sa façon de faire ou à sa mise en œuvre. Il communique ses explications ou ses solutions en utilisant des termes ou expressions spécialisés dans leur acception scientifique et technologique et différents modes de représentation.' },
    { n: 5, cycle: 3, texte: 'L’élève met en évidence des caractéristiques d’ordre scientifique ou technologique d’une problématique et dit dans ses propres mots en quoi elle consiste. Avec de l’aide dans certaines situations plus complexes, il fait des liens entre ses connaissances antérieures et ses explications provisoires pour anticiper des idées d’explication ou de solution. Il recourt à l’observation, à la manipulation, à des sources d’information variées pour choisir une ou des pistes d’explication ou de solution et justifie à l’occasion ses choix. Avec de l’aide dans certaines situations plus complexes, il choisit un moyen approprié pour recueillir les informations au cours de la mise en œuvre de l’explication ou de la solution retenue. Il choisit les outils et les instruments appropriés et les utilise en se souciant de la précision. Après un rappel, il évalue les résultats obtenus et, avec de l’aide, propose si nécessaire des modifications pertinentes à sa façon de faire ou à sa mise en œuvre, ou formule de nouvelles pistes d’explication ou de solution. Il communique ses explications ou ses solutions en utilisant des éléments des langages associés à la science et à la technologie. Il se soucie du respect des conventions dans l’utilisation des graphiques, de la notation et des symboles.' },
    { n: 6, cycle: 3, texte: 'L’élève met en évidence des caractéristiques d’ordre scientifique ou technologique d’une problématique. Il fait des liens entre les caractéristiques décelées et la problématique. Il reformule dans ses propres mots la problématique. Il fait des liens entre ses connaissances antérieures et ses explications provisoires pour anticiper des idées d’explication ou de solution. Il recourt à l’observation, à la manipulation, à des sources d’information variées pour choisir une ou des pistes d’explication ou de solution et justifie ses choix. Il choisit un moyen approprié pour recueillir les informations au cours de la mise en œuvre d’une façon de faire au regard de l’explication ou de la solution retenue. Il choisit et utilise avec précision les outils et les instruments appropriés. Il évalue les résultats obtenus et propose si nécessaire des modifications à sa façon de faire, à sa mise en œuvre ou formule de nouvelles pistes d’explication ou de solution. Il communique de façon structurée ses explications ou ses solutions en utilisant les langages associés à la science et à la technologie. Il respecte les conventions dans l’utilisation des graphiques, de la notation et des symboles.' },
  ] },
  'us_organisation': { titre: 'Lire l’organisation d’une société sur son territoire', echelons: [
    { n: 1, cycle: 2, texte: 'Dans sa production et à partir de réalités actuelles, l’élève indique avec de l’aide quelques traces laissées par la société à l’étude sur notre société et sur notre territoire. Avec de l’aide, il localise la société dans l’espace et dans le temps. Il indique avec de l’aide quelques transformations du territoire et quelques éléments d’adaptation de la société à l’étude. Il nomme des personnages ou des événements sans nécessairement les associer à l’organisation sociale et territoriale.' },
    { n: 2, cycle: 2, texte: 'Dans sa production et à partir de réalités actuelles, l’élève indique quelques traces laissées par la société à l’étude sur notre société et sur notre territoire. Il localise la société dans l’espace et dans le temps parfois de manière imprécise. Il indique quelques transformations du territoire et quelques éléments d’adaptation de la société à l’étude. Il associe souvent des personnages ou des événements à l’organisation sociale et territoriale.' },
    { n: 3, cycle: 2, texte: 'L’élève indique, à partir de réalités actuelles, des traces laissées par une société du passé sur notre société et sur notre territoire. Il reconnaît des éléments de l\'organisation de cette société sur son territoire. Il présente sa lecture de cette organisation dans une production. Il localise la société et son territoire, il indique des éléments d\'adaptation de la société au territoire qu\'elle occupe et des transformations qu\'elle y a apportées. Il associe des personnages ou des événements à l\'organisation sociale et territoriale. Il emploie, pour ce faire, un vocabulaire précis.' },
    { n: 4, cycle: 3, texte: 'L’élève, dans sa production, se limite à établir les contextes géographique et historique restreints de la société à l’étude. Avec de l\'aide, il établit parfois des liens entre des caractéristiques de la société et l’aménagement de son territoire, entre des atouts, des contraintes du territoire et l’organisation de la société. Avec de l’aide, il précise l’influence de personnages ou l’incidence d’événements sur l’organisation sociale et territoriale.' },
    { n: 5, cycle: 3, texte: 'L’élève, dans sa production, établit avec de l\'aide quelques éléments des contextes géographique et historique élargis de la société à l’étude. Avec de l\'aide, il établit des liens entre des caractéristiques de la société et l’aménagement de son territoire, ainsi qu’entre des atouts, des contraintes du territoire et l’organisation de la société. Il précise sans aide l’influence de quelques personnages ou l’incidence de quelques événements sur l’organisation sociale et territoriale.' },
    { n: 6, cycle: 3, texte: 'L’élève lit avec plus d\'aisance l\'organisation d\'une société sur son territoire et en fait état dans une production. Il indique, toujours à partir de réalités actuelles, des traces laissées par une société du passé sur notre société et sur notre territoire. Il établit les contextes géographique et historique de la société, les liens entre des caractéristiques de cette société et l’aménagement de son territoire ainsi qu’entre des atouts, des contraintes du territoire et l’organisation de la société. Il précise le rôle joué par certains personnages dans l’organisation de cette société, dans celle de son territoire ainsi que l’incidence de certains événements sur ces mêmes organisations. Il estime l’apport de cette société à la nôtre et à notre territoire. Il emploie, pour ce faire un vocabulaire précis.' },
  ] },
  'us_changement': { titre: 'Interpréter le changement dans une société et sur son territoire', echelons: [
    { n: 1, cycle: 2, texte: 'Dans sa production, l’élève reconnaît avec de l’aide des changements dans la localisation d’une société et de son territoire dans l’espace et dans le temps. Il indique avec de l’aide des changements sociaux et territoriaux et reconnaît parfois certaines causes et conséquences. Il reconnaît des personnages et des événements sans nécessairement les associer à ces changements. Avec de l’aide, il trouve dans la société ou sur le territoire actuels des traces de ces changements. Il élabore avec difficulté un point de vue sur ces changements et l’exprime parfois.' },
    { n: 2, cycle: 2, texte: 'Dans sa production, l’élève reconnaît des changements dans la localisation d’une société et de son territoire dans l’espace et dans le temps. Il indique des changements sociaux et territoriaux et leur attribue parfois des causes et des conséquences. Il reconnaît des personnages et des événements et les associe parfois à ces changements. Il trouve dans la société ou sur le territoire actuels des traces de ces changements. Il élabore un point de vue sur ces changements et l’exprime en employant parfois des arguments pertinents.' },
    { n: 3, cycle: 2, texte: 'Dans sa production, l’élève interprète des changements sociaux et territoriaux. Il reconnaît des changements dans la localisation d’une société et de son territoire dans l’espace et dans le temps à deux moments. Il relève des changements sociaux et territoriaux et en reconnaît des causes et des conséquences. Il associe des personnages ou des événements à ces changements. Il trouve dans la société et sur le territoire actuels des traces de ces changements. Il défend son interprétation de changements auprès d’autres élèves. Il emploie, pour ce faire, des arguments et un vocabulaire précis.' },
    { n: 4, cycle: 3, texte: 'L’élève, dans sa production, reconnaît avec de l’aide quelques changements dans les contextes géographiques et historiques de la société. Avec de l’aide, il décrit certains changements dans les organisations sociales et territoriales et en établit quelques causes et quelques conséquences. Il reconnaît certains personnages, mais en précise peu l’influence et leurs intérêts sur des changements. Il apporte peu de précisions sur la manière dont ces changements se manifestent aujourd’hui. Son interprétation du changement recourt difficilement à des arguments pertinents pour la justifier.' },
    { n: 5, cycle: 3, texte: 'L’élève, dans sa production, reconnaît sans aide quelques changements dans les contextes géographiques et historiques de la société. Il décrit quelques changements dans les organisations sociales et territoriales et en établit sans aide quelques causes et quelques conséquences. Il reconnaît certains personnages et en précise avec de l’aide l’influence et leurs intérêts sur des changements. Il apporte quelques précisions sur la manière dont ces changements se manifestent aujourd’hui. Il recourt à quelques arguments pertinents pour justifier son interprétation du changement.' },
    { n: 6, cycle: 3, texte: 'L’élève interprète des changements sociaux et territoriaux. Il a recours à des supports variés pour présenter son interprétation de ces changements dans une production. Il reconnaît des changements dans les contextes géographiques et historiques aux deux moments retenus pour l’étude, décrit les changements observés et en établit des causes et des conséquences. Il précise le rôle joué par certains personnages et leurs intérêts ainsi que l’incidence de certains événements sur les changements. Il cerne dans la société et sur le territoire actuels la manière dont ces changements se manifestent encore. Il défend son interprétation auprès d’autres élèves. Il emploie, pour ce faire, des arguments et un vocabulaire précis.' },
  ] },
  'us_diversite': { titre: 'S’ouvrir à la diversité des sociétés et de leur territoire', echelons: [
    { n: 1, cycle: 2, texte: 'Dans sa production, l’élève indique avec de l\'aide des différences dans la localisation des sociétés, dans l’espace et dans le temps. Dans leur organisation et dans celle de leur territoire, il énonce peu de ressemblances, de différences ou de causes et de conséquences de ces différences. Avec de l’aide, il indique quelques forces ou quelques faiblesses des organisations sociales et territoriales de ces sociétés. Il construit avec difficulté sa vision de la diversité des sociétés et de leur territoire et l’exprime parfois.' },
    { n: 2, cycle: 2, texte: 'Dans sa production, l’élève indique parfois des différences dans la localisation des sociétés, dans l’espace et dans le temps. Dans leur organisation et dans celle de leur territoire, il énonce parfois quelques ressemblances et quelques différences. Il indique quelques causes et quelques conséquences de ces différences. Il indique quelques forces et quelques faiblesses des organisations sociales et territoriales de ces sociétés. Il construit sa vision de la diversité des sociétés et de leur territoire et l’exprime en employant parfois des arguments pertinents.' },
    { n: 3, cycle: 2, texte: 'Dans sa production, l’élève présente sa vision de la diversité des sociétés et de leur territoire. Il indique des différences dans la localisation des sociétés et de leur territoire dans l’espace et dans le temps. Dans leur organisation et dans celle de leur territoire, il relève des ressemblances et des différences. Il reconnaît des causes et des conséquences de ces différences. Il précise des forces et des faiblesses des organisations sociales et territoriales de ces sociétés. Il défend sa vision de la diversité des sociétés et de leur territoire auprès d’autres élèves. Il emploie pour ce faire des arguments et un vocabulaire précis.' },
    { n: 4, cycle: 3, texte: 'L’élève, dans sa production, fait ressortir des différences dans les contextes géographiques et historiques immédiats des deux sociétés. Il décrit avec de l’aide des ressemblances et des différences dans l\'organisation des sociétés et de leur territoire, mais établit peu de causes et peu de conséquences de ces différences. Il reconnaît une force et une faiblesse des organisations sociales et territoriales.' },
    { n: 5, cycle: 3, texte: 'L’élève, dans sa production, fait ressortir avec de l’aide des différences dans les contextes géographiques et historiques élargis des deux sociétés. Il décrit sans aide des ressemblances et des différences dans l\'organisation des sociétés et de leur territoire. Il établit avec de l\'aide quelques causes et quelques conséquences de ces différences. Avec de l’aide, il établit quelques forces ou quelques faiblesses des organisations sociales et territoriales.' },
    { n: 6, cycle: 3, texte: 'L’élève présente sa vision de la diversité des sociétés et de leur territoire à l\'aide de supports variés. Il indique des différences dans les contextes géographiques et historiques des sociétés observées. Il décrit des ressemblances et des différences dans leur organisation et établit des causes et des conséquences de ces différences. Il indique des forces et des faiblesses des organisations sociales et territoriales observées. Il confronte sa vision de la diversité des sociétés et de leur territoire à celles des autres et il la défend. Il utilise, pour ce faire, des arguments et un vocabulaire précis.' },
  ] },
  'art_dram_inventer': { titre: 'Inventer des séquences dramatiques', echelons: [
    { n: 1, cycle: 1, texte: 'L’élève s’initie à des étapes de la démarche de création. Sa réalisation est souvent guidée par des intérêts d’ordre affectif. Parfois liée à la proposition de création, la séquence dramatique est courte et simple. Elle exploite des idées de création organisées au fur et à mesure. L’élève parle de son expérience de création.' },
    { n: 2, cycle: 1, texte: 'L’élève s’initie à des étapes de la démarche de création. Sa réalisation est souvent guidée par des intérêts d’ordre affectif. Liée à la proposition de création, la séquence dramatique présente une organisation simple. Elle exploite des idées de création pertinentes choisies par l’élève. L’élève mentionne des éléments signifiants pour lui, en rapport avec son expérience de création.' },
    { n: 3, cycle: 1, texte: 'L’élève participe aux étapes de la démarche de création. Sa réalisation est souvent guidée par des intérêts d’ordre affectif. Liée à la proposition de création, la séquence dramatique présente une courte fable et met en relief quelques attributs d’un personnage. Elle présente une organisation simple des éléments qui la composent, lesquels sont pertinents et variés. L’élève est capable de relater des faits concernant son expérience de création qui sont signifiants pour lui.' },
    { n: 4, cycle: 2, texte: 'L’élève participe aux étapes de la démarche de création. Souvent guidé par des intérêts d’ordre affectif et social, il traduit dans sa réalisation des aspects de la proposition de création. La séquence dramatique présente parfois une fable plus longue ou plus complexe. Elle met en relief plusieurs attributs d’un personnage. Pertinents et variés, les éléments qui composent la réalisation s’enchaînent de façon parfois continue à l’intérieur d’une organisation simple. L’élève décrit sommairement son expérience de création et en dégage parfois ce qu’il a appris.' },
    { n: 5, cycle: 2, texte: 'L’élève participe aux étapes de la démarche de création. Souvent guidé par des intérêts d’ordre affectif et social, il traduit dans sa réalisation certains aspects dominants de la proposition de création. La séquence dramatique présente une fable plus longue ou plus complexe. Elle met en relief des personnages dont les actions sont parfois plus précises. Pertinents et variés, les éléments qui composent la réalisation s’enchaînent de façon parfois continue à l’intérieur d’une organisation cohérente. L’élève décrit sommairement son expérience de création et en dégage ce qu’il a appris.' },
    { n: 6, cycle: 2, texte: 'L’élève prend en considération les étapes de la démarche de création. Souvent guidé par des intérêts d’ordre affectif et social, il traduit dans sa réalisation les aspects dominants de la proposition de création. La fable est plus développée et les actions des personnages, plus précises. Pertinents et variés, les éléments qui composent la réalisation s’enchaînent de façon continue à l’intérieur d’une organisation cohérente. L’élève décrit son expérience de création et en dégage ce qu’il a appris.' },
    { n: 7, cycle: 3, texte: 'L’élève prend en considération les étapes de la démarche de création. Sa réalisation est guidée par des intérêts d’ordre social, affectif et cognitif. Dans la séquence dramatique, il établit un rapport entre certains des éléments suivants: les personnages, le contenu de la fable, les techniques de jeu, les techniques théâtrales, les modes de théâtralisation et les structures utilisés, lesquels sont pertinents et variés. Certaines parties de la fable sont mieux définies; celle-ci présente à l’occasion une organisation complexe liée au développement de la proposition de création. L’élève décrit son expérience de création et en dégage ce qu’il a appris.' },
    { n: 8, cycle: 3, texte: 'L’élève prend en considération les étapes de la démarche de création. Sa réalisation est guidée par des intérêts d’ordre social, affectif et cognitif. Dans la séquence dramatique, il établit un rapport entre les personnages et le contenu de la fable, les techniques de jeu, les techniques théâtrales, les modes de théâtralisation et les structures utilisés, lesquels sont pertinents et variés. La fable est généralement plus définie; elle présente souvent une organisation complexe liée au développement de la proposition de création. L’élève décrit ce qu’il a appris et, à l’occasion, les moyens qu’il a utilisés.' },
    { n: 9, cycle: 3, texte: 'L’élève utilise de façon consciente chacune des étapes de la démarche de création. Sa réalisation est guidée par des intérêts d’ordre social, affectif et cognitif. Dans la séquence dramatique, il établit un rapport étroit entre les personnages, le contenu de la fable, les techniques de jeu, les techniques théâtrales, les modes de théâtralisation et les structures utilisées, lesquels sont pertinents et variés. La fable est plus définie et elle présente une organisation complexe liée au développement de la proposition de création. L’élève décrit ce qu’il a appris et les moyens qu’il a utilisés.' },
  ] },
  'art_dram_interpreter': { titre: 'Interpréter des séquences dramatiques', echelons: [
    { n: 1, cycle: 1, texte: 'L’interprétation de l’élève est gestuelle, sonore ou verbale. Elle démontre parfois une certaine précision par rapport au texte choisi. L’élève tient compte de quelques attributs de son personnage et il utilise avec un minimum de contrôle un nombre restreint d’éléments du langage dramatique, de techniques théâtrales, de modes de théâtralisation ou de structures. Le caractère expressif de son interprétation est étroitement lié à ses intérêts d’ordre affectif. L’élève parle de son expérience d’interprétation.' },
    { n: 2, cycle: 1, texte: 'L’interprétation de l\'élève est gestuelle, sonore ou verbale. Elle démontre généralement une précision relative par rapport au texte choisi. L’élève respecte quelques attributs de son personnage et il utilise avec un minimum de contrôle certains éléments du langage dramatique, de techniques théâtrales, de modes de théâtralisation ou de structures. Le caractère expressif de son interprétation est généralement lié à ses intérêts d’ordre affectif. L’élève mentionne des éléments signifiants pour lui, en rapport avec son expérience d’interprétation.' },
    { n: 3, cycle: 1, texte: 'L’interprétation de l’élève est gestuelle, sonore et verbale. Elle démontre une précision relative par rapport au texte choisi. L’élève respecte quelques attributs de son personnage et il utilise avec un minimum de contrôle les éléments du langage dramatique, de techniques de jeu, de techniques théâtrales, de modes de théâtralisation et de structures appropriés. Le caractère expressif de son interprétation est souvent lié à ses intérêts d’ordre affectif. Il est capable de relater des faits concernant son expérience d’interprétation qui sont signifiants pour lui.' },
    { n: 4, cycle: 2, texte: 'L’interprétation de l’élève est gestuelle, sonore ou verbale. Elle est parfois en accord avec le contenu de l’extrait choisi. L\'élève respecte parfois l’enchaînement des actions en tenant compte des attributs du personnage et de quelques règles relatives au jeu d’ensemble. Dans son interprétation, il allie à l’occasion ses intérêts d’ordre affectif à des éléments expressifs de l’extrait qu’il interprète. Il décrit sommairement son expérience d’interprétation et en dégage parfois ce qu’il a appris.' },
    { n: 5, cycle: 2, texte: 'L’interprétation de l’élève est gestuelle, sonore ou verbale. Elle est la plupart du temps en accord avec le contenu de l’extrait choisi. L’élève respecte souvent l’enchaînement des actions en tenant compte du personnage et parfois de quelques règles relatives au jeu d’ensemble. Dans son interprétation, il allie ses intérêts d’ordre affectif à des éléments expressifs de l’extrait qu’il interprète. Il décrit sommairement son expérience d’interprétation et en dégage ce qu’il a appris.' },
    { n: 6, cycle: 2, texte: 'L’interprétation de l’élève est gestuelle, sonore et verbale. Elle est en accord avec le contenu de l’extrait choisi, lequel est généralement plus développé. L’élève respecte l’enchaînement des actions en tenant compte du personnage et de quelques règles relatives au jeu d’ensemble. Dans son interprétation, il allie ses intérêts d’ordre affectif aux principaux éléments expressifs de l’extrait qu’il interprète. Il décrit son expérience d’interprétation et en dégage ce qu’il a appris.' },
    { n: 7, cycle: 3, texte: 'L’interprétation de l’élève est gestuelle et verbale. Elle contient certaines intentions expressives et elle est souvent en accord avec l’extrait choisi. L’élève personnalise parfois les actions de son personnage et tient généralement compte des règles relatives au jeu d’ensemble. Dans son interprétation, il allie souvent ses intérêts d’ordre affectif et cognitif aux indications de l’extrait pour mettre en évidence son caractère expressif. Il décrit son expérience d’interprétation et en dégage ce qu’il a appris.' },
    { n: 8, cycle: 3, texte: 'L’interprétation de l’élève est gestuelle et verbale. Elle contient certaines intentions expressives claires et elle est généralement en accord avec l’extrait choisi ou la courte pièce. L’élève personnalise souvent les actions de son personnage et tient compte des règles relatives au jeu d’ensemble. Dans son interprétation, il allie généralement ses intérêts d’ordre affectif et cognitif aux indications de l’extrait ou de la courte pièce pour mettre en évidence leur caractère expressif. Il décrit ce qu’il a appris et, à l’occasion, les moyens qu’il a utilisés.' },
    { n: 9, cycle: 3, texte: 'L’interprétation de l’élève est gestuelle et verbale. Elle est plus expressive et en accord avec l’extrait ou la courte pièce. L’élève personnalise les actions de son personnage et tient compte des règles relatives au jeu d’ensemble. Dans son interprétation, il allie ses intérêts d’ordre affectif et cognitif aux indications de l’extrait ou de la courte pièce pour mettre en évidence leur caractère expressif. Il décrit ce qu’il a appris et les moyens qu’il a utilisés.' },
  ] },
  'art_dram_apprecier': { titre: 'Apprécier des œuvres théâtrales, ses réalisations et celles de ses camarades', echelons: [
    { n: 1, cycle: 1, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif. En s’initiant au vocabulaire disciplinaire, l’élève nomme un élément présent dans la réalisation ou dans l’œuvre théâtrale. Son propos traduit la décision retenue à partir d’un critère d’appréciation. Sa décision est aussi liée à ce qu’il a repéré et ressenti. À la suite de son appréciation, l’élève parle de son expérience.' },
    { n: 2, cycle: 1, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif. En s’initiant au vocabulaire disciplinaire, l’élève nomme des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos traduit la décision retenue à partir de critères d’appréciation et, parfois, de certains renseignements mis à sa disposition. Sa décision est aussi liée à ce qu’il a repéré et ressenti. L’élève mentionne des éléments signifiants pour lui, en rapport avec son expérience d’appréciation.' },
    { n: 3, cycle: 1, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif. En utilisant le vocabulaire disciplinaire, l’élève nomme des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos traduit la décision retenue à partir de critères d’appréciation et de renseignements mis à sa disposition. Sa décision est aussi liée à ce qu’il a repéré et ressenti. Il est capable de relater des faits concernant son expérience d’appréciation qui sont signifiants pour lui.' },
    { n: 4, cycle: 2, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif et social. En utilisant de façon pertinente certains mots du vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et parfois socioculturel. Ces considérations sont liées aux critères d’appréciation. L’élève fait part de sa décision par rapport à ce qu’il a repéré et ressenti. L’élève décrit sommairement son expérience d’appréciation et en dégage parfois ce qu’il a appris.' },
    { n: 5, cycle: 2, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif et social. En utilisant de façon pertinente la plupart des mots du vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et parfois socioculturel. Ces considérations sont liées aux critères d’appréciation et expliquent la décision de l’élève par rapport à ce qu’il a repéré et ressenti. L’élève décrit sommairement son expérience d’appréciation et en dégage ce qu’il a appris.' },
    { n: 6, cycle: 2, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre affectif et social. En utilisant de façon pertinente le vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et parfois socioculturel. Ces considérations sont liées aux critères d’appréciation et appuient la décision retenue. L’élève décrit son expérience d’appréciation et en dégage ce qu’il a appris.' },
    { n: 7, cycle: 3, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre cognitif, affectif et social. En utilisant de façon pertinente certains mots du vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et parfois socioculturel. Ces considérations sont liées aux critères d’appréciation et expliquent sa décision par rapport à ce qu’il a repéré et ressenti. Il décrit son expérience d’appréciation et en dégage ce qu’il a appris.' },
    { n: 8, cycle: 3, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre cognitif, affectif et social. En utilisant de façon pertinente la plupart des mots du vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et socioculturel. Ces considérations sont liées aux critères d’appréciation et motivent parfois sa décision par rapport à ce qu’il a repéré et ressenti. Il décrit ce qu’il a appris et, à l’occasion, les moyens qu’il a utilisés.' },
    { n: 9, cycle: 3, texte: 'L’appréciation de l’élève est souvent guidée par des intérêts d’ordre cognitif, affectif et social. En utilisant de façon pertinente le vocabulaire disciplinaire, l’élève décrit des éléments présents dans la réalisation ou dans l’œuvre théâtrale. Son propos contient des considérations d’ordre théâtral, personnel et socioculturel. Ces considérations sont liées aux critères d’appréciation et motivent sa décision. Il décrit ce qu’il a appris et les moyens qu’il a utilisés.' },
  ] },
};
